package com.farmingdiscordstatus;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(FarmingDiscordStatusConfig.GROUP)
public interface FarmingDiscordStatusConfig extends Config
{
    String GROUP = "farmingdiscordstatus";

    @ConfigItem(
        keyName = "setupHint",
        name = "<html><table width='220' cellpadding='0' cellspacing='0'><tr>"
            + "<td><font color='#ff981f'><b>New here?</b><br>Click the Setup directions<br>checkbox below.</font></td>"
            + "<td width='22' align='center' valign='bottom'><font face='Dialog' color='#ff981f' size='+3'>&#8595;</font></td>"
            + "</tr></table></html>",
        description = "Tick Setup directions below to open the setup guide.",
        position = -2
    )
    default void setupHint()
    {
    }

    @ConfigItem(
        keyName = "setupDirections",
        name = "Setup directions — start here",
        description = "Open setup directions, the Link account button, and Send test ping. This checkbox resets after opening.",
        position = -1
    )
    default boolean setupDirections()
    {
        return false;
    }

    @ConfigItem(
        keyName = "readyPings",
        name = "Ready pings",
        description = "Ping when a farming category changes from growing to ready",
        position = 0
    )
    default boolean readyPings()
    {
        return true;
    }

    @ConfigItem(
        keyName = "linkCode",
        name = "Link code",
        description = "One-time code returned by the bot's /link command",
        position = 2
    )
    default String linkCode()
    {
        return "";
    }

    @ConfigItem(
        keyName = "linkAccount",
        name = "Link account",
        description = "Connect to Farming Status. This sends your character name, farming timer states, and ready times to farming-status-bot.onrender.com. See https://farming-status-bot.onrender.com/privacy",
        position = 3
    )
    default boolean linkAccount()
    {
        return false;
    }
}

package com.farmingdiscordstatus;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.io.IOException;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.timetracking.SummaryState;
import net.runelite.client.plugins.timetracking.Tab;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;
import net.runelite.client.plugins.timetracking.farming.FarmingTracker;
import net.runelite.client.plugins.timetracking.hunter.BirdHouseTracker;
import net.runelite.client.task.Schedule;
import net.runelite.http.api.RuneLiteAPI;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@PluginDescriptor(
    name = "Farming Discord Status",
    description = "Sends farming and birdhouse timer states to a private Discord dashboard and ready alerts",
    tags = {"farming", "birdhouse", "discord", "timers", "notifications"}
)
public class FarmingDiscordStatusPlugin extends Plugin
{
    private static final String API_TOKEN_KEY = "apiToken";
    private static final String BACKEND_URL = "https://farming-status-bot.onrender.com/";
    private static final int UPDATE_TICKS = 50;
    private static final Tab[] DISPLAY_TABS = {
        Tab.HERB, Tab.TREE, Tab.FRUIT_TREE, Tab.ALLOTMENT, Tab.FLOWER,
        Tab.BUSH, Tab.HOPS, Tab.GRAPE
    };

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private FarmingTracker farmingTracker;
    @Inject private BirdHouseTracker birdHouseTracker;
    @Inject private SplitTimerReader splitTimerReader;
    @Inject private LocationTimerReader locationTimerReader;
    @Inject private TimeTrackingConfig timeTrackingConfig;
    @Inject private FarmingDiscordStatusConfig config;
    @Inject private ConfigManager configManager;
    @Inject private OkHttpClient httpClient;
    @Inject private Gson gson;

    private final FarmingDiscordStatusSetup setupWindow = new FarmingDiscordStatusSetup();
    private int ticksUntilUpdate;
    private boolean requestInFlight;
    private volatile boolean running;

    @Provides
    FarmingDiscordStatusConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(FarmingDiscordStatusConfig.class);
    }

    @Provides
    TimeTrackingConfig provideTimeTrackingConfig(ConfigManager manager)
    {
        // RuneLite 1.13 no longer exports Time Tracking's plugin injector.
        // The readers use its saved records and configuration directly.
        return manager.getConfig(TimeTrackingConfig.class);
    }

    @Override
    protected void startUp()
    {
        running = true;
        configManager.unsetConfiguration(FarmingDiscordStatusConfig.GROUP, "webhookUrl");
        configManager.unsetConfiguration(FarmingDiscordStatusConfig.GROUP, "discordUserId");
        configManager.unsetConfiguration(FarmingDiscordStatusConfig.GROUP, "dashboardMessageId");
        configManager.unsetConfiguration(FarmingDiscordStatusConfig.GROUP, "alertMessageId");
        configManager.unsetConfiguration(FarmingDiscordStatusConfig.GROUP, "previousStates");
        configManager.unsetConfiguration(FarmingDiscordStatusConfig.GROUP, "backendUrl");
        ticksUntilUpdate = 1;
    }

    @Override
    protected void shutDown()
    {
        running = false;
        SwingUtilities.invokeLater(setupWindow::close);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!FarmingDiscordStatusConfig.GROUP.equals(event.getGroup())) return;
        if ("setupDirections".equals(event.getKey()))
        {
            if (Boolean.parseBoolean(event.getNewValue()))
            {
                configManager.setConfiguration(FarmingDiscordStatusConfig.GROUP, "setupDirections", false);
                SwingUtilities.invokeLater(() -> setupWindow.open(this::sendTestPing));
            }
            return;
        }
        ticksUntilUpdate = 1;
        if ("linkAccount".equals(event.getKey()) && Boolean.parseBoolean(event.getNewValue()))
        {
            linkAccount();
            configManager.setConfiguration(FarmingDiscordStatusConfig.GROUP, "linkAccount", false);
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN || requestInFlight) return;
        if (--ticksUntilUpdate > 0) return;
        ticksUntilUpdate = UPDATE_TICKS;
        farmingTracker.loadCompletionTimes();
        birdHouseTracker.loadFromConfig();
        List<Category> categories = collectCategories();
        HttpUrl backend = backendUrl();
        String token = stored(API_TOKEN_KEY);
        if (backend != null && token != null && !token.isEmpty())
        {
            callBackend(backend, "api/status", "PUT", backendPayload(categories), token, true);
            return;
        }
    }

    @Schedule(period = 1, unit = ChronoUnit.MINUTES, asynchronous = true)
    public void sendLoggedOutHeartbeat()
    {
        clientThread.invokeLater(() ->
        {
            if (!running || client.getGameState() != GameState.LOGIN_SCREEN) return;
            HttpUrl backend = backendUrl();
            String token = stored(API_TOKEN_KEY);
            if (backend == null || token == null || token.isEmpty()) return;
            // Heartbeats never submit patch data or generate Discord messages.
            callBackend(backend, "api/heartbeat", "POST", new LinkedHashMap<>(), token, false);
        });
    }

    private void sendTestPing()
    {
        HttpUrl backend = backendUrl();
        String token = stored(API_TOKEN_KEY);
        if (backend == null || token == null || token.isEmpty())
        {
            JOptionPane.showMessageDialog(null, "Link your account first using the setup directions.",
                "Farming Discord Status", JOptionPane.INFORMATION_MESSAGE);
            return;
        }
        callBackend(backend, "api/test", "POST", new LinkedHashMap<>(), token, false);
    }

    private void linkAccount()
    {
        HttpUrl backend = backendUrl();
        String code = config.linkCode().trim();
        if (backend == null || code.isEmpty()) return;
        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("code", code);
        callBackend(backend, "api/link", "POST", payload, null, false);
    }

    private Map<String, Object> backendPayload(List<Category> categories)
    {
        Map<String, List<LocationTimerReader.Location>> locations = locationTimerReader.collect();
        List<Map<String, Object>> rows = new ArrayList<>();
        for (Category category : categories)
        {
            Map<String, Object> row = new LinkedHashMap<>();
            row.put("key", category.key);
            row.put("name", category.name);
            row.put("state", category.state);
            row.put("readyAt", category.readyAt);
            row.put("locations", locations.getOrDefault(category.key, new ArrayList<>()));
            boolean standardRun = false;
            for (Tab tab : DISPLAY_TABS) standardRun |= tab.name().equals(category.key);
            row.put("readyWhen", "BIRD_HOUSE".equals(category.key) ? "all"
                : standardRun ? (timeTrackingConfig.preferSoonest() ? "any" : "all") : "any");
            rows.add(row);
        }
        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("player", client.getLocalPlayer() == null ? "Unknown player" : client.getLocalPlayer().getName());
        payload.put("updatedAt", System.currentTimeMillis());
        payload.put("readyPings", config.readyPings());
        payload.put("readyWhen", timeTrackingConfig.preferSoonest() ? "any" : "all");
        payload.put("categories", rows);
        return payload;
    }

    private void callBackend(HttpUrl backend, String path, String method, Map<String, Object> payload,
        String token, boolean updateRequest)
    {
        HttpUrl.Builder url = backend.newBuilder();
        for (String segment : path.split("/")) url.addPathSegment(segment);
        Request.Builder request = new Request.Builder().url(url.build());
        if (token != null) request.header("Authorization", "Bearer " + token);
        RequestBody body = jsonBody(payload);
        if ("PUT".equals(method)) request.put(body); else request.post(body);
        if (updateRequest) requestInFlight = true;
        httpClient.newCall(request.build()).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                if (updateRequest) requestInFlight = false;
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                try (Response ignored = response)
                {
                    if (response.code() == 401 && token != null)
                    {
                        configManager.unsetConfiguration(FarmingDiscordStatusConfig.GROUP, API_TOKEN_KEY);
                    }
                    if (token == null && response.isSuccessful() && response.body() != null)
                    {
                        @SuppressWarnings("unchecked")
                        Map<String, Object> result = gson.fromJson(response.body().charStream(), Map.class);
                        if (result.get("token") != null)
                        {
                            store(API_TOKEN_KEY, result.get("token").toString());
                            configManager.setConfiguration(FarmingDiscordStatusConfig.GROUP, "linkCode", "");
                            ticksUntilUpdate = 1;
                        }
                    }
                }
                finally
                {
                    if (updateRequest) requestInFlight = false;
                }
            }
        });
    }

    private List<Category> collectCategories()
    {
        long now = Instant.now().getEpochSecond();
        List<Category> categories = new ArrayList<>();
        for (Tab tab : DISPLAY_TABS)
        {
            SummaryState summary = farmingTracker.getSummary(tab);
            long completion = farmingTracker.getCompletionTime(tab);
            String state;
            if (summary == SummaryState.COMPLETED || completion == 0) state = "READY";
            else if (summary == SummaryState.EMPTY) state = "EMPTY";
            else if (summary == SummaryState.UNKNOWN) state = "UNKNOWN";
            else state = "GROWING";
            categories.add(new Category(tab.name(), displayName(tab),
                state, completion > now ? completion : 0));
        }
        addSplitCategory(categories, "MUSHROOM", "Mushroom", splitTimerReader.mushroom());
        addSplitCategory(categories, "ANIMA", "Anima", splitTimerReader.anima());
        addSplitCategory(categories, "BELLADONNA", "Belladonna", splitTimerReader.belladonna());
        addSplitCategory(categories, "CACTUS", "Cactus", splitTimerReader.cactus());
        addSplitCategory(categories, "CORAL", "Coral", splitTimerReader.coral());
        SplitTimerReader.Snapshot hespori = splitTimerReader.hespori();
        addSplitCategory(categories, "HESPORI", "Hespori", hespori);
        SplitTimerReader.Snapshot seaweed = splitTimerReader.seaweed();
        addSplitCategory(categories, "SEAWEED", "Seaweed", seaweed);
        SplitTimerReader.Snapshot compost = splitTimerReader.compost();
        addSplitCategory(categories, "COMPOST", "Compost", compost);
        SummaryState birdHouseSummary = birdHouseTracker.getSummary();
        long birdHouseCompletion = birdHouseTracker.getCompletionTime();
        String birdHouseState;
        if (birdHouseSummary == null || birdHouseSummary == SummaryState.UNKNOWN)
            birdHouseState = "UNKNOWN";
        else if (birdHouseSummary == SummaryState.EMPTY)
            birdHouseState = "EMPTY";
        else if (birdHouseSummary == SummaryState.COMPLETED
            || (birdHouseCompletion > 0 && birdHouseCompletion <= now))
            birdHouseState = "READY";
        else
            birdHouseState = "GROWING";
        categories.add(new Category("BIRD_HOUSE", "Birdhouses", birdHouseState,
            "GROWING".equals(birdHouseState) && birdHouseCompletion > now ? birdHouseCompletion : 0));
        return categories;
    }

    private static void addSplitCategory(List<Category> categories, String key, String name,
        SplitTimerReader.Snapshot snapshot)
    {
        categories.add(new Category(key, name, snapshot.getState(), snapshot.getReadyAt()));
    }

    private RequestBody jsonBody(Map<String, Object> payload)
    {
        return RequestBody.create(RuneLiteAPI.JSON, gson.toJson(payload));
    }

    private HttpUrl backendUrl()
    {
        return HttpUrl.parse(BACKEND_URL);
    }

    private String stored(String key)
    {
        return configManager.getConfiguration(FarmingDiscordStatusConfig.GROUP, key);
    }

    private void store(String key, String value)
    {
        configManager.setConfiguration(FarmingDiscordStatusConfig.GROUP, key, value);
    }

    private static String displayName(Tab tab)
    {
        switch (tab)
        {
            case HERB: return "Herbs";
            case TREE: return "Trees";
            case FRUIT_TREE: return "Fruit trees";
            case ALLOTMENT: return "Allotments";
            case FLOWER: return "Flowers";
            case BUSH: return "Bushes";
            case HOPS: return "Hops";
            case GRAPE: return "Grapes";
            case SPECIAL: return "Special patches";
            default: return tab.getName();
        }
    }

    private static final class Category
    {
        private final String key;
        private final String name;
        private final String state;
        private final long readyAt;

        private Category(String key, String name, String state, long readyAt)
        {
            this.key = key;
            this.name = name;
            this.state = state;
            this.readyAt = readyAt;
        }

    }
}

package com.farmingdiscordstatus;

import java.awt.BorderLayout;
import java.awt.GridLayout;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JDialog;
import javax.swing.WindowConstants;
import net.runelite.client.util.LinkBrowser;

final class FarmingDiscordStatusSetup
{
    private static final String DISCORD_INSTALL_URL =
        "https://discord.com/oauth2/authorize?client_id=1544867499378614363";

    private JDialog dialog;

    void close()
    {
        if (dialog != null)
        {
            dialog.dispose();
            dialog = null;
        }
    }

    void open(Runnable testPing)
    {
        if (dialog != null && dialog.isDisplayable())
        {
            dialog.toFront();
            return;
        }
        JPanel content = new JPanel(new BorderLayout(0, 16));
        content.setBorder(BorderFactory.createEmptyBorder(12, 10, 12, 10));
        JPanel setup = new JPanel(new BorderLayout(0, 12));
        setup.add(new JLabel("<html><body style='width:340px'>"
            + "<h3>Farming Discord Status</h3>"
            + "<p><b>First time? Follow these setup directions to link your account.</b></p>"
            + "<ol><li>Click <b>Link account</b> below and authorize the app in Discord.</li>"
            + "<li>DM <b>Farming Status</b> and run <b>/link</b>.</li>"
            + "<li>Paste the one-time code into <b>Link code</b> in this plugin's settings.</li>"
            + "<li>Enable <b>Link account</b> in settings once. The code clears after successful linking.</li></ol>"
            + "<p>Keep <b>Time Tracking</b> enabled and visit your patches while logged in to record timers.</p>"
            + "<p>In your Discord dashboard, click <b>Customize alerts</b> to choose categories and favorite multiple locations for separate ready pings.</p>"
            + "<p>Code not working? Run <b>/link</b> for a new one. Use <b>/unlink</b> in Discord to disconnect.</p>"
            + "</body></html>"), BorderLayout.CENTER);
        JButton link = new JButton("Link account");
        link.setToolTipText("Open Discord authorization to start linking your account");
        link.addActionListener(event -> LinkBrowser.browse(DISCORD_INSTALL_URL));
        setup.add(link, BorderLayout.SOUTH);
        content.add(setup, BorderLayout.CENTER);

        JPanel bottom = new JPanel(new GridLayout(0, 1, 0, 8));

        JButton test = new JButton("Send test ping");
        test.addActionListener(event -> testPing.run());
        bottom.add(test);

        content.add(bottom, BorderLayout.SOUTH);
        dialog = new JDialog();
        dialog.setTitle("Farming Discord Status — Setup");
        dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
        dialog.setContentPane(content);
        dialog.pack();
        dialog.setLocationRelativeTo(null);
        dialog.setVisible(true);
    }
}

package com.farmingdiscordstatus;

import com.google.gson.*;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Function;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;
import net.runelite.client.plugins.timetracking.farming.FarmingTracker;

/** Public Time Tracking records decoded with the bundled, versioned data table. */
@Singleton
public final class LocationTimerReader
{
    private final JsonObject catalog;
    private final ConfigManager configManager;
    private final FarmingTracker farmingTracker;
    private final Client client;

    @Inject
    public LocationTimerReader(ConfigManager configManager, FarmingTracker farmingTracker, Client client, Gson gson)
    {
        this.configManager = configManager;
        this.farmingTracker = farmingTracker;
        this.client = client;
        this.catalog = loadCatalog(gson);
    }

    private static JsonObject loadCatalog(Gson gson)
    {
        try (InputStreamReader reader = new InputStreamReader(Objects.requireNonNull(
            LocationTimerReader.class.getResourceAsStream("patch-catalog.json")), StandardCharsets.UTF_8))
        {
            return gson.fromJson(reader, JsonObject.class);
        }
        catch (java.io.IOException exception)
        {
            throw new IllegalStateException("Cannot read bundled patch catalog", exception);
        }
    }

    public Map<String, List<Location>> collect()
    {
        String profile = configManager.getRSProfileKey();
        boolean leagues = client.getWorldType().contains(WorldType.SEASONAL)
            && !client.getWorldType().contains(WorldType.DEADMAN);
        return collect(key -> configManager.getRSProfileConfiguration(TimeTrackingConfig.CONFIG_GROUP, key),
            (rate, ticks, timestamp) -> farmingTracker.getTickTime(rate, ticks, timestamp, profile),
            Instant.now().getEpochSecond(), leagues);
    }

    interface TickClock { long at(int rate, int ticks, long timestamp); }

    Map<String, List<Location>> collect(Function<String, String> records, TickClock clock, long now, boolean leagues)
    {
        Map<String, Map<String, List<Location>>> groups = new LinkedHashMap<>();
        for (JsonElement element : catalog.getAsJsonArray("patches"))
        {
            JsonObject patch = element.getAsJsonObject();
            String category = patch.get("category").getAsString();
            Location location = decode(patch, records.apply(patch.get("key").getAsString()), clock, now, leagues);
            groups.computeIfAbsent(category, key -> new LinkedHashMap<>())
                .computeIfAbsent(location.id, key -> new ArrayList<>()).add(location);
        }
        Map<String, List<Location>> result = new LinkedHashMap<>();
        for (Map.Entry<String, Map<String, List<Location>>> category : groups.entrySet())
        {
            List<Location> locations = new ArrayList<>();
            for (List<Location> patches : category.getValue().values()) locations.add(aggregate(patches));
            result.put(category.getKey(), locations);
        }
        List<Location> birdhouses = new ArrayList<>();
        for (JsonElement element : catalog.getAsJsonArray("birdhouses"))
        {
            JsonObject house = element.getAsJsonObject();
            long[] record = record(records.apply(house.get("key").getAsString()));
            Location location = location(house, "UNKNOWN", 0);
            if (record != null && record[0] >= 0 && record[0] <= house.get("maxValue").getAsInt())
            {
                if (record[0] == 0) location = location(house, "EMPTY", 0);
                else if (record[0] % 3 != 0) location = location(house, "FILLING", 0);
                else
                {
                    long readyAt = record[1] + house.get("duration").getAsInt();
                    location = location(house, readyAt <= now ? "READY" : "GROWING", readyAt <= now ? 0 : readyAt);
                }
            }
            birdhouses.add(location);
        }
        result.put("BIRD_HOUSE", birdhouses);
        return result;
    }

    private Location decode(JsonObject patch, String stored, TickClock clock, long now, boolean leagues)
    {
        long[] record = record(stored);
        JsonArray values = catalog.getAsJsonObject("decoders").getAsJsonArray(patch.get("implementation").getAsString());
        if (record == null || record[0] < 0 || record[0] >= values.size() || values.get((int) record[0]).isJsonNull())
            return location(patch, "UNKNOWN", 0);
        JsonArray decoded = values.get((int) record[0]).getAsJsonArray();
        String state = decoded.get(0).getAsString();
        if (!state.equals("GROWING") && !state.equals("HARVESTABLE")) return location(patch, state, 0);
        int rate = decoded.get(1).getAsInt();
        int ticks = decoded.get(2).getAsInt();
        if (leagues) rate /= 5;
        long readyAt = rate <= 0 || ticks <= 0 ? 0 : clock.at(rate, ticks, clock.at(rate, 0, record[1]));
        return location(patch, readyAt <= now ? "READY" : "GROWING", readyAt <= now ? 0 : readyAt);
    }

    private static long[] record(String stored)
    {
        if (stored == null) return null;
        String[] parts = stored.split(":", -1);
        if (parts.length != 2) return null;
        try
        {
            long timestamp = Long.parseLong(parts[1]);
            return timestamp > 0 ? new long[]{ Integer.parseInt(parts[0]), timestamp } : null;
        }
        catch (NumberFormatException ignored) { return null; }
    }

    private static Location location(JsonObject patch, String state, long readyAt)
    {
        return new Location(patch.get("locationId").getAsString(), patch.get("location").getAsString(), state, readyAt);
    }

    static Location aggregate(List<Location> patches)
    {
        // Wait for every growing patch at this location, ignoring empty or
        // unobserved patches. For example, north/south allotments share one ping.
        for (String state : Arrays.asList("GROWING", "READY", "DISEASED", "DEAD", "FILLING", "EMPTY", "UNKNOWN"))
        {
            if (patches.stream().anyMatch(patch -> patch.state.equals(state)))
            {
                long readyAt = state.equals("GROWING")
                    ? patches.stream().filter(patch -> patch.state.equals(state)).mapToLong(patch -> patch.readyAt).max().orElse(0) : 0;
                Location first = patches.get(0);
                return new Location(first.id, first.name, state, readyAt);
            }
        }
        throw new IllegalArgumentException("No patches at this location");
    }

    static final class Location
    {
        final String id;
        final String name;
        final String state;
        final long readyAt;
        Location(String id, String name, String state, long readyAt)
        {
            this.id = id; this.name = name; this.state = state; this.readyAt = readyAt;
        }
    }
}

package com.farmingdiscordstatus;

import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;
import net.runelite.client.plugins.timetracking.farming.FarmingTracker;

/** Reads individual public Time Tracking configuration records without internal API access. */
@Singleton
public class SplitTimerReader
{
    private static final String HESPORI_KEY = "5021." + VarbitID.FARMING_TRANSMIT_J;
    private static final String MUSHROOM_KEY = "13622." + VarbitID.FARMING_TRANSMIT_A;
    private static final String ANIMA_KEY = "4922." + VarbitID.FARMING_TRANSMIT_M;
    private static final String[] BELLADONNA_KEYS = {
        "5427." + VarbitID.FARMING_TRANSMIT_B,
        "12340." + VarbitID.FARMING_TRANSMIT_A
    };
    private static final String[] CACTUS_KEYS = {
        "13106." + VarbitID.FARMING_TRANSMIT_A,
        "4922." + VarbitID.FARMING_TRANSMIT_F
    };
    private static final String[] CORAL_KEYS = {
        "12581." + VarbitID.FARMING_TRANSMIT_A,
        "12581." + VarbitID.FARMING_TRANSMIT_B
    };
    private static final String[] SEAWEED_KEYS = {
        "15008." + VarbitID.FARMING_TRANSMIT_A,
        "15008." + VarbitID.FARMING_TRANSMIT_B
    };
    private static final String[] COMPOST_KEYS = {
        "10548." + VarbitID.FARMING_TRANSMIT_E,
        "11062." + VarbitID.FARMING_TRANSMIT_E,
        "6192." + VarbitID.FARMING_TRANSMIT_E,
        "12083." + VarbitID.FARMING_TRANSMIT_E,
        "6967." + VarbitID.FARMING_TRANSMIT_E,
        "14391." + VarbitID.FARMING_TRANSMIT_E,
        "4922." + VarbitID.FARMING_TRANSMIT_N,
        "13151." + VarbitID.FARMING_TRANSMIT_D
    };

    private final ConfigManager configManager;
    private final FarmingTracker farmingTracker;

    @Inject
    public SplitTimerReader(ConfigManager configManager, FarmingTracker farmingTracker)
    {
        this.configManager = configManager;
        this.farmingTracker = farmingTracker;
    }

    public Snapshot hespori()
    {
        Record record = record(HESPORI_KEY);
        if (record == null) return Snapshot.unknown();
        if (record.value >= 7 && record.value <= 8) return Snapshot.ready();
        if (record.value >= 4 && record.value <= 6)
        {
            return growing(record, 640, 4, record.value - 4);
        }
        return Snapshot.empty();
    }

    public Snapshot mushroom()
    {
        Record record = record(MUSHROOM_KEY);
        if (record == null) return Snapshot.unknown();
        if (between(record.value, 10, 15)) return Snapshot.ready();
        if (between(record.value, 4, 9)) return growing(record, 40, 7, record.value - 4);
        return Snapshot.empty();
    }

    public Snapshot anima()
    {
        Record record = record(ANIMA_KEY);
        if (record == null) return Snapshot.unknown();
        int stage;
        if (between(record.value, 8, 16)) stage = record.value - 8;
        else if (between(record.value, 17, 25)) stage = record.value - 17;
        else if (between(record.value, 26, 34)) stage = record.value - 26;
        else return Snapshot.empty();
        return growing(record, 640, 9, stage);
    }

    public Snapshot belladonna()
    {
        Aggregate aggregate = new Aggregate();
        for (String key : BELLADONNA_KEYS)
        {
            Record record = record(key);
            if (record == null) continue;
            if (record.value == 8) aggregate.add(Snapshot.ready());
            else if (between(record.value, 4, 7))
                aggregate.add(growing(record, 80, 5, record.value - 4));
            else aggregate.add(Snapshot.empty());
        }
        return aggregate.result();
    }

    public Snapshot cactus()
    {
        Aggregate aggregate = new Aggregate();
        for (String key : CACTUS_KEYS)
        {
            Record record = record(key);
            if (record == null) continue;
            if (between(record.value, 15, 18) || between(record.value, 39, 45))
                aggregate.add(Snapshot.ready());
            else if (between(record.value, 8, 14))
                aggregate.add(growing(record, 80, 8, record.value - 8));
            else if (record.value == 31) aggregate.add(growing(record, 80, 8, 7));
            else if (between(record.value, 32, 38))
                aggregate.add(growing(record, 10, 8, record.value - 32));
            else if (record.value == 58) aggregate.add(growing(record, 10, 8, 7));
            else aggregate.add(Snapshot.empty());
        }
        return aggregate.result();
    }

    public Snapshot coral()
    {
        Aggregate aggregate = new Aggregate();
        for (String key : CORAL_KEYS)
        {
            Record record = record(key);
            if (record == null) continue;
            int stage;
            if (between(record.value, 4, 8)) stage = record.value - 4;
            else if (between(record.value, 15, 19)) stage = record.value - 15;
            else if (between(record.value, 26, 30)) stage = record.value - 26;
            else
            {
                aggregate.add(Snapshot.empty());
                continue;
            }
            aggregate.add(growing(record, 40, 5, stage));
        }
        return aggregate.result();
    }

    public Snapshot seaweed()
    {
        Aggregate aggregate = new Aggregate();
        for (String key : SEAWEED_KEYS)
        {
            Record record = record(key);
            if (record == null) continue;
            if (record.value >= 8 && record.value <= 10) aggregate.add(Snapshot.ready());
            else if (record.value >= 4 && record.value <= 7)
                aggregate.add(growing(record, 10, 5, record.value - 4));
            else aggregate.add(Snapshot.empty());
        }
        return aggregate.result();
    }

    public Snapshot compost()
    {
        Aggregate aggregate = new Aggregate();
        for (int index = 0; index < COMPOST_KEYS.length; index++)
        {
            Record record = record(COMPOST_KEYS[index]);
            if (record == null) continue;
            boolean big = index == 6;
            if (isReadyCompost(record.value, big)) aggregate.add(Snapshot.ready());
            else if (record.value == 0) aggregate.add(Snapshot.empty());
            else if (compostGrowthStage(record.value, big) >= 0)
                aggregate.add(growing(record, 40, 3, compostGrowthStage(record.value, big)));
            else aggregate.add(new Snapshot("GROWING", 0));
        }
        return aggregate.result();
    }

    private Snapshot growing(Record record, int tickRate, int stages, int stage)
    {
        String profile = configManager.getRSProfileKey();
        long observedTick = farmingTracker.getTickTime(tickRate, 0, record.timestamp, profile);
        long readyAt = farmingTracker.getTickTime(tickRate, stages - 1 - stage,
            observedTick, profile);
        return readyAt <= Instant.now().getEpochSecond()
            ? Snapshot.ready() : new Snapshot("GROWING", readyAt);
    }

    private Record record(String key)
    {
        String stored = configManager.getRSProfileConfiguration(TimeTrackingConfig.CONFIG_GROUP, key);
        if (stored == null) return null;
        String[] parts = stored.split(":", 2);
        if (parts.length != 2) return null;
        try
        {
            return new Record(Integer.parseInt(parts[0]), Long.parseLong(parts[1]));
        }
        catch (NumberFormatException ignored)
        {
            return null;
        }
    }

    static boolean isReadyCompost(int value, boolean big)
    {
        if (between(value, 16, 30) || between(value, 48, 62)
            || between(value, 144, 158)) return true;
        if (big)
        {
            return value == 93 || value == 99 || value == 222
                || between(value, 78, 92) || between(value, 100, 114)
                || between(value, 176, 205) || between(value, 207, 221);
        }
        return value == 94 || value == 126 || between(value, 176, 190);
    }

    // Closed bins retain a growing-state record; predict completion using
    // the same 40-minute farming ticks and three stages as Time Tracking.
    static int compostGrowthStage(int value, boolean big)
    {
        if (between(value, 159, 160)) return value - 159;
        if (big)
        {
            if (between(value, 127, 128)) return value - 127;
            if (between(value, 97, 98)) return value - 97;
        }
        else
        {
            if (between(value, 31, 32)) return value - 31;
            if (between(value, 95, 96)) return value - 95;
        }
        return -1;
    }

    private static boolean between(int value, int minimum, int maximum)
    {
        return value >= minimum && value <= maximum;
    }

    private static final class Record
    {
        private final int value;
        private final long timestamp;

        private Record(int value, long timestamp)
        {
            this.value = value;
            this.timestamp = timestamp;
        }
    }

    private static final class Aggregate
    {
        private boolean known;
        private boolean ready;
        private boolean growing;
        private long soonest = Long.MAX_VALUE;

        private void add(Snapshot snapshot)
        {
            known = !"UNKNOWN".equals(snapshot.state);
            ready |= "READY".equals(snapshot.state);
            growing |= "GROWING".equals(snapshot.state);
            if (snapshot.readyAt > 0) soonest = Math.min(soonest, snapshot.readyAt);
        }

        private Snapshot result()
        {
            if (!known) return Snapshot.unknown();
            if (ready) return Snapshot.ready();
            if (growing) return new Snapshot("GROWING", soonest == Long.MAX_VALUE ? 0 : soonest);
            return Snapshot.empty();
        }
    }

    public static final class Snapshot
    {
        private final String state;
        private final long readyAt;

        private Snapshot(String state, long readyAt)
        {
            this.state = state;
            this.readyAt = readyAt;
        }

        private static Snapshot unknown() { return new Snapshot("UNKNOWN", 0); }
        private static Snapshot empty() { return new Snapshot("EMPTY", 0); }
        private static Snapshot ready() { return new Snapshot("READY", 0); }
        public String getState() { return state; }
        public long getReadyAt() { return readyAt; }
    }
}

package com.farmingdiscordstatus;

import org.junit.Test;
import static org.junit.Assert.*;

public class CompostStateTest
{
    @Test
    public void finishedClosedBinsAreReadyBeforeOpening()
    {
        // Actual saved records behind the reported mismatch: normal
        // supercompost is 126, and Farming Guild supercompost is 99.
        assertTrue(SplitTimerReader.isReadyCompost(126, false));
        assertTrue(SplitTimerReader.isReadyCompost(99, true));
